/tell-us-about-your-situation.script:
function render(P) {
  const v = P.viewer || {};
  const persona = v.persona || "";
  const sessions = (P.data && P.data.intake_sessions) || [];
  const s = sessions.find(x => x.user_id === v.id) || null;
  const text = s && s.situation_text ? String(s.situation_text) : "";
  const hasText = text.trim().length > 0;

  const instMap = {
    government: "Government school",
    government_aided: "Government-aided school",
    private: "Private school"
  };
  const incomeMap = {
    very_low: "Very low",
    low: "Low",
    middle: "Middle",
    high: "Higher"
  };

  const classVal = s && s.class_level ? "Class " + s.class_level : null;
  const instVal = s && s.institution_type ? (instMap[s.institution_type] || s.institution_type) : null;
  const stateVal = s && s.state ? s.state : null;
  const incomeVal = s && s.income_level ? (incomeMap[s.income_level] || s.income_level) : null;

  const details = [
    ["Class level", classVal],
    ["Institution type", instVal],
    ["State", stateVal],
    ["Income level", incomeVal]
  ];

  const detailItems = details.map(([label, val]) => `
        <li class="ui-list-item">
          <div class="ui-list-main"><strong>${P.esc(label)}</strong></div>
          <div class="ui-list-side">${val
            ? `<span class="ui-badge ui-badge-success">${P.esc(val)}</span>`
            : `<span class="ui-meta">Not yet known</span>`}</div>
        </li>`).join("");

  const who = persona === "Parent"
    ? "Describe your child's situation in one sentence."
    : "Describe your own situation in one sentence.";

  const examples = [
    "My daughter is in Class 11 at a government school and our income is low.",
    "I am in Class 12 at a government-aided school and my family income is very low.",
    "My son studies in Class 11 at a government school in Tamil Nadu, and we have a low income."
  ];

  const exampleButtons = examples.map(e => `
        <button class="ui-card ui-card-link" type="button" style="text-align:left">
          <div class="ui-card-body"><p>${P.esc(e)}</p></div>
        </button>`).join("");

  const voiceNote = s && s.input_method === "voice"
    ? `<div class="ui-alert ui-alert-info">Transcribed from your voice. Check the text before you continue.</div>`
    : "";

  const understood = hasText
    ? `<div class="ui-card">
        <div class="ui-card-header"><h3>What we understood</h3></div>
        <div class="ui-card-body">
          <ul class="ui-list">${detailItems}
          </ul>
        </div>
      </div>`
    : `<div class="ui-empty">
        <p class="ui-empty-title">Nothing yet</p>
        <p class="ui-empty-text">Your details will appear here once a sentence is read. Missing details show as Not yet known.</p>
      </div>`;

  const continueBtn = hasText
    ? `<a class="ui-btn ui-btn-primary" href="/follow-up-question-flow">Continue</a>`
    : `<span class="ui-btn ui-btn-primary is-disabled" aria-disabled="true">Continue</span>`;

  return `
<div class="ui-page">
  <div class="ui-page-header">
    <div>
      <h1>Tell us about your situation</h1>
      <p class="ui-meta">Say or type one sentence. We will ask only a few quick questions.</p>
    </div>
    <div class="ui-actions"><a class="ui-btn ui-btn-ghost" href="/">Back</a></div>
  </div>

  <div class="ui-stack">
    <section class="ui-section">
      <div class="ui-tabs" role="group" aria-label="Language">
        <button class="ui-tab is-active" type="button">English</button>
        <button class="ui-tab" type="button">தமிழ்</button>
      </div>
      <p class="ui-meta">${P.esc(who)} We do not ask for Aadhaar numbers, bank details or document uploads here.</p>
    </section>

    <section class="ui-section">
      <div class="ui-row">
        <div class="ui-field" style="flex:1">
          <span>Your sentence</span>
          <textarea class="ui-textarea" id="situation" rows="4" placeholder="For example: My daughter is in Class 11 at a government school and our income is low.">${P.esc(text)}</textarea>
          <span class="ui-help">You can edit this sentence at any time. The details below will update.</span>
        </div>
        <button class="ui-btn ui-btn-secondary" type="button">Speak</button>
      </div>
      ${voiceNote}
    </section>

    <section class="ui-section">
      <h2 class="ui-section-title">Try an example</h2>
      <div class="ui-grid ui-grid-3">${exampleButtons}
      </div>
    </section>

    <section class="ui-section">
      <h2 class="ui-section-title">What we understood</h2>
      ${understood}
    </section>

    <section class="ui-section">
      <div class="ui-row">
        ${continueBtn}
        <a class="ui-link" href="/privacy-and-how-haqpath-decides">Why do we ask?</a>
      </div>
      <p class="ui-meta">Eligibility is not decided on this screen. HaqPath only picks up details from your sentence.</p>
    </section>
  </div>
</div>`;
}

/follow-up-question-flow.script:
function render(P) {
  const esc = v => P.esc(v == null ? '' : String(v));
  const viewer = P.viewer || {};
  const sessions = P.data.intake_sessions || [];
  const parents = P.data.parent_profiles || [];
  const students = P.data.student_profiles || [];

  // Find this person's intake: their own, or their parent's for a student.
  let intake = sessions.find(s => s.user_id === viewer.id);
  if (!intake) {
    const pp = parents.find(p => p.child_user_id === viewer.id);
    if (pp) intake = sessions.find(s => s.user_id === pp.user_id);
  }
  if (!intake) intake = {};

  const sp = students.find(s => s.user_id === viewer.id);
  const classLevel = intake.class_level || (sp && sp.class_level) || '';
  const instType = intake.institution_type || (sp && sp.institution_type) || '';

  // Question catalogue, highest value first.
  const Q = [
    {
      key: 'household_income_annual', req: 'required',
      title: "What is your household's yearly income?",
      why: 'Income limits decide which schemes your family can receive.',
      options: [['100000', 'Up to ₹1 lakh a year'], ['180000', '₹1 lakh to ₹2 lakh a year'], ['250000', 'Over ₹2 lakh a year']]
    },
    {
      key: 'category', req: 'required',
      title: 'Which community category does your family belong to?',
      why: 'Some scholarships are only open to certain categories.',
      options: [['scheduled_caste', 'Scheduled Caste (SC)'], ['scheduled_tribe', 'Scheduled Tribe (ST)'], ['backward_class', 'Backward Class (BC or MBC)'], ['general', 'General / Open']]
    },
    {
      key: 'selected_in_merit_test', req: 'optional',
      title: 'Has the student been selected in a merit test?',
      why: 'Some scholarships pick students through a merit list.',
      options: [['yes', 'Yes'], ['no', 'No']]
    },
    {
      key: 'passed_previous_hsc', req: 'optional',
      title: 'Did the student pass the previous class in the last exam?',
      why: 'Many schemes ask for a pass in the previous year.',
      options: [['yes', 'Yes'], ['no', 'No']]
    }
  ];
  const total = Q.length;
  const qKeys = Q.map(q => q.key);

  const rows = (P.data.follow_up_answers || [])
    .filter(a => a.intake_session_id === intake.id)
    .sort((a, b) => (a.captured_order || 0) - (b.captured_order || 0));

  const labelFor = (key, val) => {
    const q = Q.find(x => x.key === key);
    const o = q && q.options.find(x => x[0] === String(val));
    if (o) return o[1];
    if (key === 'household_income_annual' && val != null && val !== '' && !isNaN(Number(val))) {
      return P.fmt.money(Number(val));
    }
    return String(val == null ? '' : val).replace(/_/g, ' ');
  };
  const keyLabel = key => {
    const map = {
      household_income_annual: 'Household income',
      category: 'Community category',
      selected_in_merit_test: 'Selected in merit test',
      passed_previous_hsc: 'Passed previous class'
    };
    return map[key] || String(key || '').replace(/_/g, ' ');
  };

  const instLabel = { government: 'Government school', government_aided: 'Government-aided school' };
  const incomeLabel = { very_low: 'Very low income', low: 'Low income' };

  // Profile details from the first sentence
  const profileItems = [];
  if (classLevel) profileItems.push(['Class', 'Class ' + classLevel]);
  if (instType) profileItems.push(['School type', instLabel[instType] || instType.replace(/_/g, ' ')]);
  if (intake.state) profileItems.push(['State', intake.state]);
  if (intake.income_level) profileItems.push(['Income level', incomeLabel[intake.income_level] || intake.income_level.replace(/_/g, ' ')]);

  const profileHtml = profileItems.map(([k, v]) => `
    <li class="ui-list-item">
      <div class="ui-list-main"><strong>${esc(v)}</strong><span class="ui-meta">${esc(k)} · from your first answer</span></div>
      <div class="ui-list-side"><button class="ui-btn ui-btn-ghost ui-btn-sm" type="button">Edit</button></div>
    </li>`).join('');

  const answerHtml = rows.filter(r => qKeys.includes(r.question_key) || r.question_key).map(r => {
    const skipped = r.status === 'skipped';
    const badge = skipped
      ? '<span class="ui-badge ui-badge-neutral">Skipped</span>'
      : '<span class="ui-badge ui-badge-success">Answered</span>';
    const value = skipped ? 'Not answered' : labelFor(r.question_key, r.answer);
    return `
    <li class="ui-list-item">
      <div class="ui-list-main"><strong>${esc(value)}</strong><span class="ui-meta">${esc(keyLabel(r.question_key))}</span></div>
      <div class="ui-list-side">${badge} <button class="ui-btn ui-btn-ghost ui-btn-sm" type="button">Edit</button></div>
    </li>`;
  }).join('');

  const understoodHtml = (profileHtml + answerHtml) || '';

  // Question progress
  const qRows = rows.filter(r => qKeys.includes(r.question_key));
  const answeredCount = qRows.filter(r => r.status === 'answered').length;
  const skippedCount = qRows.filter(r => r.status === 'skipped').length;
  const doneCount = answeredCount + skippedCount;
  const pct = Math.min(100, Math.round((doneCount / total) * 100));
  const stepNum = Math.min(doneCount + 1, total);

  const pendingQ = Q.find(q => !qRows.some(r => r.question_key === q.key));
  const requiredDone = Q.filter(q => q.req === 'required')
    .every(q => qRows.some(r => r.question_key === q.key && r.status === 'answered'));

  let card = '';
  if (pendingQ) {
    const optional = pendingQ.req === 'optional';
    const reqBadge = optional
      ? '<span class="ui-badge ui-badge-neutral">Optional</span>'
      : '<span class="ui-badge ui-badge-info">Required</span>';
    const opts = pendingQ.options.map(([v, l]) =>
      `<button class="ui-btn ui-btn-secondary" type="button" data-value="${esc(v)}">${esc(l)}</button>`
    ).join('');
    const skipBtn = optional
      ? `<button class="ui-btn ui-btn-secondary" type="button">Skip this question</button>
         <p class="ui-help">Schemes that depend on this answer will show as May qualify, with this detail to verify.</p>`
      : '';
    card = `
    <div class="ui-card">
      <div class="ui-card-header"><h3>${esc(pendingQ.title)}</h3>${reqBadge}</div>
      <div class="ui-card-body">
        <p class="ui-meta">Why we ask this: ${esc(pendingQ.why)}</p>
        <div class="ui-grid ui-grid-2">${opts}</div>
      </div>
      <div class="ui-card-footer">
        <div class="ui-actions">
          <button class="ui-btn ui-btn-primary" type="button">Next</button>
          ${skipBtn}
          <button class="ui-btn ui-btn-ghost" type="button">Read aloud</button>
        </div>
      </div>
    </div>`;
  } else {
    card = `
    <div class="ui-alert ui-alert-success">We have all the answers we need for now.</div>`;
  }

  const resultsBtn = requiredDone
    ? `<div class="ui-actions"><a class="ui-btn ui-btn-primary" href="/results">See my results</a></div>`
    : `<p class="ui-meta">Answer the required questions to see your results.</p>`;

  return `
<div class="ui-page">
  <div class="ui-page-header">
    <div>
      <h1>A few quick questions</h1>
      <p class="ui-meta">You can skip optional questions. Each answer helps us check eligibility.</p>
      <p class="ui-meta">Question ${stepNum} of ${total}</p>
    </div>
  </div>

  <section class="ui-section">
    <h2 class="ui-section-title">What we understood so far</h2>
    <ul class="ui-list">${understoodHtml || '<li class="ui-list-item"><div class="ui-list-main"><span class="ui-meta">Nothing captured yet.</span></div></li>'}</ul>
  </section>

  <section class="ui-section">
    <h2 class="ui-section-title">Current question</h2>
    ${card}
  </section>

  <section class="ui-section">
    <h2 class="ui-section-title">Your progress</h2>
    <div class="ui-progress"><span style="width:${pct}%"></span></div>
    <p class="ui-meta">${answeredCount} answered · ${skippedCount} skipped · ${total - doneCount} to go</p>
    ${resultsBtn}
  </section>

  <section class="ui-section">
    <div class="ui-alert ui-alert-info">Your answers are used only to check eligibility. HaqPath does not ask for Aadhaar numbers, bank details or document scans.</div>
    <p class="ui-meta">HaqPath provides guidance based on published rules. Final eligibility is decided by the relevant authority.</p>
  </section>
</div>`;
}

/results.script:
function render(P) {
  const esc = v => P.esc(v == null ? '' : v);
  const D = P.data || {};
  const list = k => (Array.isArray(D[k]) ? D[k] : []);
  const viewer = P.viewer || {};
  const isParent = viewer.persona === 'Parent';

  // Find the family's intake: the viewer's own, or the parent's for a student.
  const intakes = list('intake_sessions');
  let intake = intakes.find(i => i.user_id === viewer.id);
  if (!intake) {
    const pp = list('parent_profiles').find(p => p.child_user_id === viewer.id);
    if (pp) intake = intakes.find(i => i.user_id === pp.user_id);
  }
  intake = intake || {};

  const answers = list('follow_up_answers')
    .filter(a => a.intake_session_id === intake.id)
    .slice()
    .sort((a, b) => (a.captured_order || 0) - (b.captured_order || 0));
  const getAns = k => answers.find(a => a.question_key === k && a.status === 'answered');

  const humanize = v => v == null ? '' : String(v).replace(/_/g, ' ').replace(/^./, c => c.toUpperCase());
  const QLABEL = {
    category: 'Category',
    household_income_annual: 'Annual household income',
    passed_previous_hsc: 'Passed previous HSC',
    resident_of_tamil_nadu: 'Resident of Tamil Nadu',
    selected_in_merit_test: 'Selected in merit test'
  };
  const qLabel = k => QLABEL[k] || humanize(k);
  const instLabel = t => ({ government: 'Government school', government_aided: 'Government-aided school' })[t] || humanize(t);
  const ansText = a => {
    if (!a) return 'Skipped';
    if (a.question_key === 'household_income_annual') {
      const n = Number(a.answer);
      return isNaN(n) ? String(a.answer) : P.fmt.money(n);
    }
    if (a.answer === 'yes') return 'Yes';
    return humanize(a.answer);
  };

  const incomeAns = getAns('household_income_annual');
  const incomeNum = incomeAns ? Number(incomeAns.answer) : NaN;

  function evaluate(s) {
    const r = s.eligibility_rules || {};
    const fails = [], unknown = [], passes = [];

    if (Array.isArray(r.state) && r.state.length) {
      if (r.state.includes(intake.state)) passes.push('state');
      else fails.push(`it is for students in ${r.state.join(' or ')}.`);
    }
    if (Array.isArray(r.class_levels) && r.class_levels.length) {
      if (r.class_levels.map(String).includes(String(intake.class_level))) passes.push('class level');
      else fails.push(`it is for students in Class ${r.class_levels.join(' and ')}.`);
    }
    if (Array.isArray(r.institution_types) && r.institution_types.length) {
      if (r.institution_types.includes(intake.institution_type)) passes.push('institution type');
      else fails.push(`it is for students in ${r.institution_types.map(instLabel).join(' or ')} schools.`);
    }
    const mk = Object.keys(r).find(k => /^max_annual/.test(k));
    if (mk && typeof r[mk] === 'number') {
      if (!incomeAns || isNaN(incomeNum)) unknown.push('annual household income');
      else if (incomeNum > r[mk]) fails.push(`the published income limit is ${P.fmt.money(r[mk])} and the household income is above it.`);
      else passes.push('income');
    }
    ['category', 'categories', 'passed_previous_hsc', 'resident_of_tamil_nadu', 'selected_in_merit_test'].forEach(k => {
      if (!(k in r)) return;
      const qk = k === 'categories' ? 'category' : k;
      const label = qLabel(qk).toLowerCase();
      const a = getAns(qk);
      const rule = r[k];
      if (!a) { unknown.push(label); return; }
      if (Array.isArray(rule)) {
        if (rule.includes(a.answer)) passes.push(label);
        else fails.push(`the ${label} rule is not met by the answer given.`);
      } else if (rule === true) {
        if (a.answer === 'yes') passes.push(label);
        else fails.push(`this scheme needs ${label}.`);
      }
    });

    if (fails.length) {
      return { group: 'not', reason: `Not matched right now because ${fails[0]}` };
    }
    if (unknown.length) {
      return {
        group: 'may',
        reason: passes.length ? `Your ${passes.join(', ')} fit the rules so far.` : 'Your answers fit the main rules so far.',
        confirm: `your ${unknown[0]}.`
      };
    }
    return {
      group: 'likely',
      reason: passes.length ? `Matches your ${passes.join(', ')}.` : 'Matches the answers you gave.'
    };
  }

  const schemes = list('schemes');
  const groups = { likely: [], may: [], not: [] };
  schemes.forEach(s => {
    const e = evaluate(s);
    groups[e.group].push({ s, e });
  });

  const card = ({ s, e }) => {
    const badge = e.group === 'likely'
      ? '<span class="ui-badge ui-badge-success">Likely eligible</span>'
      : e.group === 'may'
        ? '<span class="ui-badge ui-badge-warning">May qualify</span>'
        : '<span class="ui-badge ui-badge-neutral">Not currently eligible</span>';
    const label = e.group === 'not' ? 'Reason' : 'Why this may fit';
    const confirm = e.group === 'may'
      ? `<p class="ui-meta">To confirm: ${esc(e.confirm)}</p>`
      : '';
    return `<div class="ui-card">
      <div class="ui-card-header"><h3>${esc(s.name)}</h3>${badge}</div>
      <div class="ui-card-body">
        <p>${esc(s.short_description)}</p>
        <p><strong>${label}:</strong> ${esc(e.reason)}</p>
        ${confirm}
      </div>
      <div class="ui-card-footer"><a class="ui-btn ui-btn-secondary ui-btn-sm" href="/schemes/${esc(s.id)}">Open</a></div>
    </div>`;
  };

  const section = (key, title, empty) => {
    const items = groups[key];
    const body = items.length
      ? `<div class="ui-grid ui-grid-2">${items.map(card).join('')}</div>`
      : `<div class="ui-empty"><p class="ui-empty-text">${esc(empty)}</p></div>`;
    return `<section class="ui-section">
      <h2 class="ui-section-title">${esc(title)} <span class="ui-meta">${items.length} ${items.length === 1 ? 'scheme' : 'schemes'}</span></h2>
      ${body}
    </section>`;
  };

  // Answers used for matching, in the order asked.
  const answerRows = [
    ['Class level', intake.class_level ? `Class ${intake.class_level}` : '—'],
    ['Institution type', intake.institution_type ? instLabel(intake.institution_type) : '—'],
    ...answers.map(a => [qLabel(a.question_key), ansText(a)]),
    ['State', intake.state || '—']
  ];
  const answersHtml = answerRows.map(([label, value]) => `<li class="ui-list-item">
      <div class="ui-list-main"><strong>${esc(label)}</strong><span class="ui-meta">${esc(value)}</span></div>
      ${isParent ? '<div class="ui-list-side"><a class="ui-btn ui-btn-ghost ui-btn-sm" href="/follow-up-question-flow">Change</a></div>' : ''}
    </li>`).join('');

  const dates = schemes.map(s => s.last_verified_at).filter(Boolean).sort();
  const lastVerified = dates.length ? P.fmt.date(dates[dates.length - 1]) : '—';

  return `<div class="ui-page">
  <div class="ui-page-header">
    <div>
      <h1>Your scheme results</h1>
      <p class="ui-meta">Based on the answers you gave. Final eligibility is decided by the relevant authority.</p>
    </div>
    <div class="ui-actions"><button class="ui-btn ui-btn-primary" type="button">Read aloud</button></div>
  </div>

  <section class="ui-section">
    <h2 class="ui-section-title">Your answers</h2>
    <ul class="ui-list">${answersHtml}</ul>
  </section>

  ${section('likely', 'Likely eligible', 'No schemes are likely eligible from these answers yet.')}
  ${section('may', 'May qualify', 'No schemes need confirming at the moment.')}
  ${section('not', 'Not currently eligible', 'No schemes are outside the rules at the moment.')}

  <section class="ui-section">
    <div class="ui-alert ui-alert-info">
      <p>HaqPath provides guidance based on published rules. Final eligibility is decided by the relevant authority.</p>
      <p class="ui-meta">Last verified on ${esc(lastVerified)}</p>
    </div>
  </section>
</div>`;
}

/schemes/{}.script:
function render(P) {
  const e = P.esc;
  const data = P.data || {};
  const coll = k => (Array.isArray(data[k]) ? data[k] : []);
  const v = P.viewer || {};
  const s = P.find('schemes', P.params && P.params.id);

  if (!s) {
    return `<div class="ui-page">
  <div class="ui-page-header"><div><h1>Scheme not found</h1></div></div>
  <section class="ui-section"><div class="ui-empty"><p class="ui-empty-title">This scheme is not in the current list</p><a class="ui-btn ui-btn-primary" href="/results">Back to results</a></div></section>
</div>`;
  }

  const list = x => (Array.isArray(x) ? x : (x == null || x === '' ? [] : [x]));
  const txt = x => {
    if (x == null) return '';
    if (typeof x === 'string') return x;
    if (typeof x === 'object') return String(x.text || x.label || x.name || x.title || x.description || '');
    return String(x);
  };
  const lbl = x => String(x == null ? '' : x).replace(/_/g, ' ');
  const cap = x => (x ? x.charAt(0).toUpperCase() + x.slice(1) : '');
  const eq = (a, b) => String(a).toLowerCase() === String(b).toLowerCase();
  const money = n => P.fmt.money(n);

  // Find the student's intake session (own, or the child's via parent profile)
  const intakes = coll('intake_sessions');
  let intake = intakes.find(r => r.user_id === v.id);
  if (!intake) {
    const pp = coll('parent_profiles').find(r => r.child_user_id === v.id);
    if (pp) intake = intakes.find(r => r.user_id === pp.user_id);
  }
  const answers = coll('follow_up_answers').filter(a => intake && a.intake_session_id === intake.id && a.status !== 'skipped');
  const ans = key => {
    const a = answers.find(r => r.question_key === key);
    return a ? a.answer : undefined;
  };
  const ansFor = key => {
    const a = answers.find(r => r.question_key === key || key.includes(r.question_key) || String(r.question_key).includes(key));
    return a ? a.answer : undefined;
  };

  const rules = (s.eligibility_rules && typeof s.eligibility_rules === 'object') ? s.eligibility_rules : {};
  const matched = [], open = [], unmet = [];

  for (const [key, val] of Object.entries(rules)) {
    if (val == null || val === '' || val === false) continue;
    let title = '', has = false, ok = false, yourAnswer = '', covers = '';

    if (key === 'state') {
      title = 'State';
      const exp = list(val);
      const uv = intake ? intake.state : undefined;
      has = uv != null && uv !== '';
      ok = has && exp.some(x => eq(x, uv));
      yourAnswer = has ? String(uv) : '';
      covers = exp.map(lbl).join(', ');
    } else if (key === 'class_levels') {
      title = 'Class level';
      const exp = list(val);
      const uv = intake ? intake.class_level : undefined;
      has = uv != null && uv !== '';
      ok = has && exp.some(x => eq(x, uv));
      yourAnswer = has ? 'Class ' + uv : '';
      covers = 'Class ' + exp.join('–');
    } else if (key === 'institution_types') {
      title = 'School type';
      const exp = list(val);
      const uv = intake ? intake.institution_type : undefined;
      has = uv != null && uv !== '';
      ok = has && exp.some(x => eq(x, uv));
      yourAnswer = has ? lbl(uv) : '';
      covers = exp.map(lbl).join(', ');
    } else if (/income/.test(key)) {
      const lim = Number(val);
      if (isNaN(lim)) continue;
      title = 'Annual household income';
      const raw = ans('household_income_annual');
      const n = Number(raw);
      has = raw !== undefined && raw !== '' && !isNaN(n);
      ok = has && n <= lim;
      yourAnswer = has ? money(n) : '';
      covers = 'up to ' + money(lim);
    } else {
      title = cap(lbl(key));
      const uv = ansFor(key);
      has = uv !== undefined && uv !== '';
      if (val === true) {
        ok = has && eq(uv, 'yes');
        covers = 'Yes';
      } else {
        const exp = list(val);
        ok = has && exp.some(x => eq(x, uv));
        covers = exp.map(lbl).join(', ');
      }
      yourAnswer = has ? lbl(uv) : '';
    }

    const item = { title, yourAnswer, covers };
    if (!has) {
      open.push({
        title,
        reason: `We do not have your answer for "${title}" yet, so this rule is still open.`,
        how: `Keep the official proof for ${title.toLowerCase()} ready and confirm it on the official website before you apply.`
      });
    } else if (ok) {
      matched.push(item);
    } else {
      unmet.push(item);
    }
  }

  const status = unmet.length ? 'Not currently eligible' : (open.length ? 'May qualify' : 'Likely eligible');
  const statusCls = status === 'Likely eligible' ? 'ui-badge-success' : (status === 'May qualify' ? 'ui-badge-warning' : 'ui-badge-danger');
  const icon = status === 'Likely eligible' ? '✓' : (status === 'May qualify' ? '?' : '✕');

  const docs = list(s.required_documents).map(txt).filter(Boolean);
  const steps = list(s.application_steps).map(txt).filter(Boolean);

  const dl = Date.parse(String(s.deadline) + 'T00:00:00Z');
  const td = Date.parse(String(P.today) + 'T00:00:00Z');
  const days = Math.round((dl - td) / 864e5);
  const daysText = isNaN(days) ? '—' : (days < 0 ? 'Deadline has passed' : (days === 0 ? 'Due today' : `${days} days left`));
  const host = txt(s.official_url).replace(/^https?:\/\//, '').split('/')[0] || '—';

  const isStudent = /Student/.test(v.persona || '');
  const saved = coll('saved_schemes').find(r => r.user_id === v.id && r.scheme_id === s.id);

  const ruleItems = arr => arr.map(r => `<li class="ui-list-item"><div class="ui-list-main"><strong>${e(r.title)}</strong><span class="ui-meta">Scheme covers: ${e(r.covers)}</span></div><div class="ui-list-side"><span class="ui-meta">Your answer: ${e(r.yourAnswer || '—')}</span></div></li>`).join('');

  const matchedHtml = matched.length
    ? `<ul class="ui-list">${matched.map(r => `<li class="ui-list-item"><div class="ui-list-main"><strong>${e(r.title)} — ${e(r.covers)}</strong><span class="ui-meta">Your answer: ${e(r.yourAnswer || '—')}</span></div><div class="ui-list-side"><span class="ui-badge ui-badge-success">Matches</span></div></li>`).join('')}</ul>`
    : `<div class="ui-empty"><p class="ui-empty-text">No matched rules to show yet.</p></div>`;

  const openHtml = open.length
    ? `<ul class="ui-list">${open.map(r => `<li class="ui-list-item"><div class="ui-list-main"><strong>${e(r.title)}</strong><span class="ui-meta">${e(r.reason)}</span><span class="ui-meta">How to confirm: ${e(r.how)}</span></div><div class="ui-list-side"><span class="ui-badge ui-badge-warning">Open</span></div></li>`).join('')}</ul>`
    : '';

  const unmetHtml = unmet.length
    ? `<ul class="ui-list">${unmet.map(r => `<li class="ui-list-item"><div class="ui-list-main"><strong>${e(r.title)}</strong><span class="ui-meta">This scheme covers ${e(r.covers)}, and your answer is ${e(r.yourAnswer || '—')}. The published rules may have other options, so please check the official rules.</span></div><div class="ui-list-side"><span class="ui-badge ui-badge-neutral">Not met</span></div></li>`).join('')}</ul>`
    : '';

  const docsHtml = docs.length
    ? `<ul class="ui-list">${docs.map(d => `<li class="ui-list-item"><div class="ui-list-main"><span>${e(d)}</span></div></li>`).join('')}</ul>`
    : `<p class="ui-meta">No documents listed.</p>`;

  const stepsHtml = steps.length
    ? `<ol>${steps.map(st => `<li><p>${e(st)}</p></li>`).join('')}</ol>`
    : `<p class="ui-meta">No application steps listed.</p>`;

  const saveHtml = isStudent
    ? (saved
        ? `<span class="ui-badge ui-badge-info">Already in your checklist</span> <a class="ui-btn ui-btn-primary" href="/document-checklist-and-application-steps">Open my checklist</a>`
        : `<a class="ui-btn ui-btn-primary" href="/document-checklist-and-application-steps">Save to my checklist</a>`)
    : '';

  return `<div class="ui-page">
  <div class="ui-stack">
    <div class="ui-row">
      <a class="ui-link" href="/results">Back to results</a>
      <span class="ui-badge ${statusCls}">${icon} ${e(status)}</span>
    </div>
  </div>

  <div class="ui-page-header">
    <div><h1>${e(s.name)}</h1><p class="ui-meta">${e(s.short_description)}</p></div>
  </div>

  <section class="ui-section">
    <div class="ui-card">
      <div class="ui-card-body">
        <dl class="ui-kv">
          <dt>State</dt><dd>${e(s.state)}</dd>
          <dt>Beneficiary group</dt><dd>${e(s.beneficiary_group)}</dd>
          <dt>Estimated benefit</dt><dd>${e(s.estimated_benefit)}</dd>
        </dl>
        ${s.plain_language_explanation ? `<p>${e(txt(s.plain_language_explanation))}</p>` : ''}
      </div>
    </div>
  </section>

  <div class="ui-alert ui-alert-info"><strong>Last verified on ${e(P.fmt.date(s.last_verified_at))}</strong> · Official source: ${e(host)}</div>

  <section class="ui-section">
    <h2 class="ui-section-title">Why this may fit</h2>
    ${matchedHtml}
  </section>

  ${open.length ? `<section class="ui-section"><h2 class="ui-section-title">What we still need to verify</h2>${openHtml}</section>` : ''}

  ${unmet.length ? `<section class="ui-section"><h2 class="ui-section-title">Why this may not fit</h2>${unmetHtml}</section>` : ''}

  <section class="ui-section">
    <h2 class="ui-section-title">Documents, deadline and how to apply</h2>
    <div class="ui-grid ui-grid-3">
      <div class="ui-card">
        <div class="ui-card-header"><h3>Required documents</h3></div>
        <div class="ui-card-body">${docsHtml}</div>
      </div>
      <div class="ui-card">
        <div class="ui-card-header"><h3>Deadline</h3></div>
        <div class="ui-card-body">
          <div class="ui-stat"><span class="ui-stat-label">Closes</span><span class="ui-stat-value">${e(P.fmt.date(s.deadline))}</span><span class="ui-stat-note">${e(daysText)}</span></div>
        </div>
      </div>
      <div class="ui-card">
        <div class="ui-card-header"><h3>How to apply</h3></div>
        <div class="ui-card-body">${stepsHtml}</div>
      </div>
    </div>
    <div class="ui-actions">
      <a class="ui-btn ui-btn-secondary" href="${e(txt(s.official_url))}" target="_blank" rel="noopener">Official website</a>
    </div>
  </section>

  <section class="ui-section">
    <h2 class="ui-section-title">Actions</h2>
    <div class="ui-actions">
      <button class="ui-btn ui-btn-secondary" type="button">Read aloud</button>
      ${saveHtml}
    </div>
    <p class="ui-meta">HaqPath provides guidance based on published rules. Final eligibility is decided by the relevant authority.</p>
    <p><a class="ui-link" href="/privacy-and-how-haqpath-decides">How HaqPath decides</a></p>
  </section>
</div>`;
}

/document-checklist-and-application-step.script:
function render(P) {
  const esc = P.esc;
  const data = P.data || {};
  const v = P.viewer || {};
  const dt = x => (x ? P.fmt.date(x) : "—");
  const owners = [v.id];
  (data.parent_profiles || []).forEach(pp => {
    if (pp.user_id === v.id && pp.child_user_id) owners.push(pp.child_user_id);
  });
  const items = data.checklist_items || [];
  const toList = x => {
    if (Array.isArray(x)) {
      return x
        .map(i => typeof i === "string" ? i : (i && (i.name || i.label || i.title || i.text || i.step || i.description)) || "")
        .filter(Boolean);
    }
    if (typeof x === "string") return x.split(/\n|;/).map(s => s.trim()).filter(Boolean);
    return [];
  };
  const statusLabel = { not_started: "Not started", documents_ready: "Documents ready", applied: "Applied", awaiting_outcome: "Awaiting outcome" };
  const statusBadge = { not_started: "ui-badge-neutral", documents_ready: "ui-badge-info", applied: "ui-badge-success", awaiting_outcome: "ui-badge-warning" };
  const isTicked = (ss, type, label) =>
    items.some(i => i.saved_scheme_id === ss.id && i.item_type === type && i.label === label && i.ticked);

  const saved = (data.saved_schemes || [])
    .filter(s => owners.includes(s.user_id))
    .map(s => ({ ss: s, sc: P.find("schemes", s.scheme_id) || {} }))
    .sort((a, b) => String(a.sc.deadline || "9999").localeCompare(String(b.sc.deadline || "9999")));

  const rows = saved.map(({ ss, sc }) => {
    const docs = toList(sc.required_documents).map(label => ({ label, on: isTicked(ss, "document", label) }));
    const steps = toList(sc.application_steps).map(label => ({ label, on: isTicked(ss, "step", label) }));
    const docsOn = docs.filter(d => d.on).length;
    const stepsOn = steps.filter(s => s.on).length;
    const total = docs.length + steps.length;
    const done = docsOn + stepsOn;
    const pct = total ? Math.round((done / total) * 100) : 0;
    return { ss, sc, docs, steps, docsOn, stepsOn, pct };
  });

  const totalDocs = rows.reduce((n, r) => n + r.docs.length, 0);
  const totalDocsOn = rows.reduce((n, r) => n + r.docsOn, 0);
  const totalSteps = rows.reduce((n, r) => n + r.steps.length, 0);
  const totalStepsOn = rows.reduce((n, r) => n + r.stepsOn, 0);

  const header = `
  <div class="ui-page-header">
    <div><h1>Your checklist and how to apply</h1><p class="ui-meta">The steps on this page come from official sources.</p></div>
    <div class="ui-actions">
      <button class="ui-btn ui-btn-secondary" type="button">Read aloud</button>
      <select class="ui-select" aria-label="Language"><option>English</option><option>தமிழ்</option></select>
    </div>
  </div>`;

  if (!rows.length) {
    return `<div class="ui-page">${header}
  <section class="ui-section">
    <div class="ui-empty">
      <p class="ui-empty-title">No schemes saved yet</p>
      <p class="ui-empty-text">Pick schemes from Results first. Your checklist and steps will appear here.</p>
      <a class="ui-btn ui-btn-primary" href="/results">Go to Results</a>
    </div>
  </section>
  <section class="ui-section"><p class="ui-help">HaqPath provides guidance based on published rules. Final eligibility is decided by the relevant authority. <a class="ui-link" href="/privacy-and-how-haqpath-decides">How HaqPath decides</a></p></section>
</div>`;
  }

  const progressSection = `
  <section class="ui-section">
    <h2 class="ui-section-title">Your progress</h2>
    <div class="ui-grid ui-grid-2">
      <div class="ui-stat"><span class="ui-stat-label">Documents ready</span><span class="ui-stat-value">${totalDocsOn} of ${totalDocs}</span><span class="ui-stat-note">Across ${rows.length} saved ${rows.length === 1 ? "scheme" : "schemes"}</span></div>
      <div class="ui-stat"><span class="ui-stat-label">Steps done</span><span class="ui-stat-value">${totalStepsOn} of ${totalSteps}</span><span class="ui-stat-note">Across ${rows.length} saved ${rows.length === 1 ? "scheme" : "schemes"}</span></div>
    </div>
    <ul class="ui-list">
      ${rows.map(r => `<li class="ui-list-item"><div class="ui-list-main"><strong>${esc(r.sc.name || "Scheme")}</strong><span class="ui-meta">${r.docsOn} of ${r.docs.length} documents · ${r.stepsOn} of ${r.steps.length} steps</span></div><div class="ui-list-side"><span class="ui-badge ${statusBadge[r.ss.progress_status] || "ui-badge-neutral"}">${esc(statusLabel[r.ss.progress_status] || "Not started")}</span></div></li>`).join("")}
    </ul>
    <p><a class="ui-link" href="/deadline-and-progress-tracker">View deadlines and progress</a></p>
  </section>`;

  const cards = `
  <section class="ui-section">
    <h2 class="ui-section-title">Scheme checklists</h2>
    <div class="ui-grid ui-grid-2">
      ${rows.map(r => `
      <article class="ui-card">
        <div class="ui-card-header"><h3><a class="ui-link" href="/schemes/${esc(r.sc.id || r.ss.scheme_id)}">${esc(r.sc.name || "Scheme")}</a></h3><span class="ui-badge ${statusBadge[r.ss.progress_status] || "ui-badge-neutral"}">${esc(statusLabel[r.ss.progress_status] || "Not started")}</span></div>
        <div class="ui-card-body">
          <p>${esc(r.sc.short_description || "")}</p>
          <p class="ui-meta"><strong>Last verified on ${esc(dt(r.sc.last_verified_at))}</strong></p>
          <dl class="ui-kv"><dt>Deadline</dt><dd>${esc(dt(r.sc.deadline))}</dd><dt>Progress</dt><dd>${r.docsOn} of ${r.docs.length} documents · ${r.stepsOn} of ${r.steps.length} steps</dd></dl>
          <div class="ui-progress"><span style="width:${r.pct}%"></span></div>
          <p><strong>Documents needed</strong></p>
          ${r.docs.length ? `<ul class="ui-list">${r.docs.map(d => `<li class="ui-list-item"><label class="ui-check"><input type="checkbox"${d.on ? " checked" : ""}> ${esc(d.label)}</label></li>`).join("")}</ul>` : `<p class="ui-meta">No documents listed.</p>`}
        </div>
        <div class="ui-card-footer"><a class="ui-link" href="${esc(r.sc.official_url || "#")}" target="_blank" rel="noopener">Official source</a></div>
      </article>`).join("")}
    </div>
  </section>`;

  const stepsSection = `
  <section class="ui-section">
    <h2 class="ui-section-title">Application steps</h2>
    ${rows.map(r => `
    <div class="ui-card">
      <div class="ui-card-header"><h3>${esc(r.sc.name || "Scheme")}</h3><span class="ui-meta">${r.stepsOn} of ${r.steps.length} done</span></div>
      <div class="ui-card-body">
        ${r.steps.length ? `<ol class="ui-timeline">${r.steps.map((s, i) => `<li class="ui-timeline-item"><span class="ui-timeline-time">Step ${i + 1}</span><p><label class="ui-check"><input type="checkbox"${s.on ? " checked" : ""}> ${esc(s.label)}</label></p>${i === r.steps.length - 1 ? `<p><a class="ui-link" href="${esc(r.sc.official_url || "#")}" target="_blank" rel="noopener">Go to the official source</a></p>` : ""}</li>`).join("")}</ol>` : `<p class="ui-meta">No steps listed yet.</p>`}
      </div>
    </div>`).join("")}
  </section>`;

  const saveBar = `
  <section class="ui-section">
    <div class="ui-card"><div class="ui-card-body">
      <div class="ui-actions">
        <button class="ui-btn ui-btn-primary" type="button">Save checklist</button>
        <button class="ui-btn ui-btn-secondary" type="button">Share this checklist with family</button>
      </div>
      <p class="ui-help">Sharing creates a plain text summary of scheme names, documents, steps and deadlines.</p>
    </div></div>
  </section>`;

  const footer = `
  <section class="ui-section">
    <div class="ui-alert ui-alert-info">HaqPath provides guidance based on published rules. Final eligibility is decided by the relevant authority.</div>
    <p><a class="ui-link" href="/results">Back to results</a> · <a class="ui-link" href="/privacy-and-how-haqpath-decides">How HaqPath decides</a></p>
  </section>`;

  return `<div class="ui-page">
  ${header}
  ${progressSection}
  ${cards}
  ${stepsSection}
  ${saveBar}
  ${footer}
</div>`;
}

/deadline-and-progress-tracker.script:
function render(P) {
  const esc = P.esc;
  const data = P.data || {};
  const viewer = P.viewer || {};
  const isParent = viewer.persona === 'Parent';

  const STEPS = [
    { key: 'not_started', label: 'Not started', icon: '○' },
    { key: 'documents_ready', label: 'Documents ready', icon: '▤' },
    { key: 'applied', label: 'Applied', icon: '✎' },
    { key: 'awaiting_outcome', label: 'Awaiting outcome', icon: '⏳' }
  ];

  const toDay = (s) => {
    const m = String(s || '').match(/^(\d{4})-(\d{2})-(\d{2})/);
    return m ? Date.UTC(+m[1], +m[2] - 1, +m[3]) / 86400000 : null;
  };
  const today = toDay(P.today);
  const find = (c, id) => {
    try { return P.find(c, id) || null; } catch (e) { return null; }
  };
  const fmtDate = (v) => {
    if (!v) return '—';
    try { return esc(P.fmt.date(v)); } catch (e) { return esc(v); }
  };

  // Whose saved schemes are shown
  let ownerId = viewer.id;
  let childName = '';
  if (isParent) {
    const pp = (data.parent_profiles || []).find(p => p.user_id === viewer.id);
    ownerId = pp ? pp.child_user_id : null;
    const child = ownerId ? find('users', ownerId) : null;
    childName = child ? child.name : '';
  }

  const saved = (data.saved_schemes || [])
    .filter(r => r.user_id === ownerId)
    .slice()
    .sort((a, b) => String(a.saved_at || '').localeCompare(String(b.saved_at || '')));

  const items = saved.map(r => {
    const scheme = find('schemes', r.scheme_id) || {};
    const deadlineDay = toDay(scheme.deadline);
    const days = (deadlineDay !== null && today !== null) ? deadlineDay - today : null;
    const passed = days !== null && days < 0;
    const status = STEPS.some(s => s.key === r.progress_status) ? r.progress_status : 'not_started';
    const idx = STEPS.findIndex(s => s.key === status);
    return { r, scheme, days, passed, status, idx };
  });

  const countdownText = (it) => {
    if (it.days === null) return '—';
    if (it.passed) return 'Deadline passed';
    if (it.days === 0) return 'Closes today';
    return `Closes in ${it.days} ${it.days === 1 ? 'day' : 'days'}`;
  };

  // Deadline notices: within 7 days and not yet passed
  const soon = items.filter(it => it.days !== null && !it.passed && it.days <= 7);
  const notices = soon.map(it => `
    <div class="ui-alert ui-alert-warning">Closing soon: <strong>${esc(it.scheme.name || 'Scheme')}</strong> ${esc(countdownText(it).toLowerCase())}, on ${fmtDate(it.scheme.deadline)}.</div>`).join('');

  const keyHtml = STEPS.map(s => `
      <div class="ui-stat"><span class="ui-stat-label">${esc(s.icon)} Step</span><span class="ui-stat-value">${esc(s.label)}</span></div>`).join('');

  const cards = items.map(it => {
    const sc = it.scheme;
    const track = STEPS.map((s, i) => {
      const cls = i < it.idx ? 'ui-badge-success' : (i === it.idx ? 'ui-badge-info' : 'ui-badge-neutral');
      return `<span class="ui-badge ${cls}">${esc(s.icon)} ${esc(s.label)}</span>`;
    }).join(' ');
    const current = STEPS[it.idx] ? STEPS[it.idx].label : 'Not started';
    const updateBtn = isParent ? '' : `<button class="ui-btn ui-btn-primary" type="button">Update progress</button>`;
    return `
    <div class="ui-card">
      <div class="ui-card-header"><h3><a class="ui-link" href="/schemes/${esc(sc.id || it.r.scheme_id)}">${esc(sc.name || 'Scheme')}</a></h3><span class="ui-badge ${it.passed ? 'ui-badge-danger' : 'ui-badge-info'}">${esc(countdownText(it))}</span></div>
      <div class="ui-card-body">
        <dl class="ui-kv">
          <dt>Deadline</dt><dd>${fmtDate(sc.deadline)}</dd>
          <dt>Last verified</dt><dd>${fmtDate(sc.last_verified_at)}</dd>
          <dt>Progress</dt><dd><strong>${esc(current)}</strong></dd>
        </dl>
        <div class="ui-row">${track}</div>
      </div>
      <div class="ui-card-footer">
        ${updateBtn}
        <a class="ui-link" href="/document-checklist-and-application-steps">View checklist</a>
      </div>
    </div>`;
  }).join('');

  const listHtml = items.length
    ? `<div class="ui-grid ui-grid-2">${cards}</div>`
    : `<div class="ui-empty">
        <p class="ui-empty-title">No schemes saved yet</p>
        <p class="ui-empty-text">Save a checklist from your results to track deadlines here.</p>
        <a class="ui-btn ui-btn-primary" href="/results">Go to results</a>
      </div>`;

  const latestVerified = items
    .map(it => it.scheme.last_verified_at)
    .filter(Boolean)
    .sort()
    .slice(-1)[0];

  const intro = isParent && childName
    ? `<p class="ui-meta">Showing deadlines for ${esc(childName)}.</p>`
    : '';

  return `
<div class="ui-page">
  <div class="ui-page-header">
    <div>
      <h1>Deadlines and progress</h1>
      <p class="ui-meta">Track each scheme from start to outcome.</p>
      ${intro}
    </div>
    <div class="ui-actions"><a class="ui-link" href="/results">Back to results</a></div>
  </div>

  <section class="ui-section">
    <h2 class="ui-section-title">Progress key</h2>
    <div class="ui-grid ui-grid-4">${keyHtml}
    </div>
  </section>

  <section class="ui-section">
    <h2 class="ui-section-title">Your deadlines</h2>
    <div class="ui-stack">
      ${notices}
      ${listHtml}
    </div>
  </section>

  <section class="ui-section">
    <div class="ui-stack">
      <p class="ui-meta">Last verified on ${latestVerified ? fmtDate(latestVerified) : '—'}</p>
      <p class="ui-meta">HaqPath provides guidance based on published rules. Final eligibility is decided by the relevant authority.</p>
      <div class="ui-actions"><button class="ui-btn ui-btn-ghost ui-btn-sm" type="button">Read aloud</button></div>
    </div>
  </section>
</div>`;
}

/demo-mode.script:
function render(P) {
  const esc = (v) => P.esc(v == null ? "" : v);
  const coll = (name) => (P.data && Array.isArray(P.data[name]) ? P.data[name] : []);
  const parents = coll("parent_profiles");
  const students = coll("student_profiles");
  const intakes = coll("intake_sessions");

  const instLabel = (t) => {
    if (t === "government") return "a government school";
    if (t === "government_aided") return "a government-aided school";
    return "a school";
  };

  const cards = parents.map((pp, i) => {
    const parent = P.find("users", pp.user_id) || {};
    const child = P.find("users", pp.child_user_id) || {};
    const student = students.find((s) => s.user_id === pp.child_user_id) || null;
    const intake = intakes.find((s) => s.user_id === pp.user_id) || null;
    const parentName = parent.name ? `${parent.name}'s family` : "Fictional family";
    const cls = student && student.class_level ? student.class_level : "–";
    const inst = student ? instLabel(student.institution_type) : "a school";
    const town = pp.town || "";
    const state = pp.state || "";
    const place = [town, state].filter(Boolean).join(", ");
    const incomeTxt = intake && intake.income_level
      ? (intake.income_level === "very_low" ? "very low" : intake.income_level)
      : "low";
    const situation = `${pp.relationship ? pp.relationship.charAt(0).toUpperCase() + pp.relationship.slice(1) : "Parent"} of a Class ${cls} student at ${inst}${place ? " in " + place : ""}, with ${incomeTxt} household income.`;
    const schoolName = student && student.school_name ? student.school_name : "";
    return `
    <div class="ui-card">
      <div class="ui-card-header">
        <div><h3>${esc(parentName)}</h3><p class="ui-meta">Class ${esc(cls)} · ${esc(schoolName)}</p></div>
        <span class="ui-badge ui-badge-neutral">Fictional</span>
      </div>
      <div class="ui-card-body">
        <p>${esc(situation)}</p>
        <p class="ui-meta">Persona ${i + 1} of ${parents.length}</p>
      </div>
      <div class="ui-card-footer">
        <a class="ui-btn ui-btn-primary" href="/results">Load this profile</a>
      </div>
    </div>`;
  }).join("");

  const personaBlock = cards
    ? `<div class="ui-stack">${cards}</div>`
    : `<div class="ui-empty">
         <p class="ui-empty-title">No demo profiles are loaded yet</p>
         <p class="ui-empty-text">Demo profiles are stored separately from the app. Use the built-in copy to continue.</p>
         <a class="ui-link" href="/">Back to Welcome</a>
       </div>`;

  return `
<div class="ui-page">
  <div class="ui-page-header">
    <div>
      <h1>Demo Mode</h1>
      <p class="ui-meta">These are fictional family profiles for judges to try.</p>
    </div>
  </div>

  <section class="ui-section">
    <div class="ui-alert ui-alert-info">
      All profiles on this screen are made up. No real personal data is used, and no Aadhaar, bank or document details are entered.
    </div>
  </section>

  <section class="ui-section">
    <h2 class="ui-section-title">Preloaded personas</h2>
    ${personaBlock}
  </section>

  <section class="ui-section">
    <h2 class="ui-section-title">Demo switch</h2>
    <div class="ui-card">
      <div class="ui-card-body">
        <form class="ui-form">
          <label class="ui-check"><input type="checkbox"> Demo mode</label>
          <p class="ui-meta">Demo mode is off for this visit. Turn it on by loading a profile above.</p>
          <div class="ui-actions">
            <button class="ui-btn ui-btn-secondary" type="button">Turn demo mode off</button>
          </div>
        </form>
      </div>
    </div>
  </section>

  <div class="ui-actions">
    <a class="ui-link" href="/">Back to Welcome</a>
  </div>
</div>`;
}
